// ================= chapter 2 — HOW HE DEFENDS (demonstration, real time, side-on): close fast, sink low, watch the ball, block it cleanly =================
const C2={strong:A(1,'Gabriel was'),how:A(1,'This is'),close:A(1,'gets close'),fast:A(1,'fast'),low:A(1,'stays low'),knees:A(1,'knees'),watch:A(1,'watches'),tricks:A(1,'not the'),step:A(1,'Then he'),takes:A(1,'takes it'),clean:A(1,'cleanly'),end:AUTH[1].seconds};
const T2:TackleT={close:C2.close-.1,arrive:C2.fast+.5,trick:C2.tricks-.15,step:C2.step+.3,hit:Math.max(C2.step+.62,C2.takes),out:C2.clean+.15};
